namespace Maxx.Domain.Academico;

// A base que a faculdade abastece. Estar nela não é ter conta: o Usuario do passo 3 se
// liga a uma linha daqui, uma para uma. O papel vem daqui, nunca do domínio do e-mail.
public sealed class CadastroElegivel
{
    // Para o EF Core materializar do banco.
    private CadastroElegivel()
    {
        Email = null!;
        NomeCompleto = null!;
    }

    private CadastroElegivel(
        Papeis papeis, string? ra, string email, string nomeCompleto, Guid? cursoId, int? semestre)
    {
        Id = Guid.CreateVersion7();
        Papeis = papeis;
        Ra = ra;
        Email = email;
        NomeCompleto = nomeCompleto;
        CursoId = cursoId;
        Semestre = semestre;
    }

    public Guid Id { get; private set; }

    public Papeis Papeis { get; private set; }

    // Identidade interna e credencial de login do aluno. Opcional para os outros papéis.
    public string? Ra { get; private set; }

    public string Email { get; private set; }

    public string NomeCompleto { get; private set; }

    // Só do aluno: curso atual e semestre do aluno (perfil, não pontua).
    public Guid? CursoId { get; private set; }

    public int? Semestre { get; private set; }

    public bool EhAluno => Papeis == Papeis.Aluno;

    public bool EhProfessor => Papeis.HasFlag(Papeis.Professor);

    public static CadastroElegivel Aluno(string ra, string email, string nomeCompleto, Curso curso, int semestre)
    {
        ArgumentNullException.ThrowIfNull(curso);

        if (semestre < 1 || semestre > curso.DuracaoEmSemestres)
        {
            throw new DomainException(
                $"O curso {curso.Sigla} vai do semestre 1 ao {curso.DuracaoEmSemestres}, não tem o {semestre}.");
        }

        return new CadastroElegivel(
            Papeis.Aluno,
            Texto.Obrigatorio(ra, "O RA do aluno"),
            ValidarEmail(email),
            Texto.Obrigatorio(nomeCompleto, "O nome completo"),
            curso.Id,
            semestre);
    }

    public static CadastroElegivel Professor(string email, string nomeCompleto, bool tambemInstituicao = false, string? ra = null) =>
        Funcionario(tambemInstituicao ? Papeis.Professor | Papeis.Instituicao : Papeis.Professor, email, nomeCompleto, ra);

    public static CadastroElegivel Instituicao(string email, string nomeCompleto, string? ra = null) =>
        Funcionario(Papeis.Instituicao, email, nomeCompleto, ra);

    private static CadastroElegivel Funcionario(Papeis papeis, string email, string nomeCompleto, string? ra) =>
        new(
            papeis,
            ra is null ? null : Texto.Obrigatorio(ra, "O RA"),
            ValidarEmail(email),
            Texto.Obrigatorio(nomeCompleto, "O nome completo"),
            cursoId: null,
            semestre: null);

    // Só a forma. Os domínios aceitos são configuração do passo 3.
    private static string ValidarEmail(string email)
    {
        email = Texto.Obrigatorio(email, "O e-mail");
        var arroba = email.IndexOf('@', StringComparison.Ordinal);
        if (arroba <= 0 || arroba != email.LastIndexOf('@') || arroba == email.Length - 1)
        {
            throw new DomainException($"E-mail inválido: {email}.");
        }

        return email;
    }
}
namespace Maxx.Domain.Academico;

// Aluno nunca acumula papel. O único acúmulo possível é professor e instituição na
// mesma conta.
[Flags]
public enum Papeis
{
    Nenhum = 0,
    Aluno = 1,
    Professor = 2,
    Instituicao = 4,
}
namespace Maxx.Domain.Academico;

// Professor cadastrado por turma, a cada semestre. É a fonte do escopo de turma checado
// no banco a cada mutação de prêmio.
public sealed class VinculoProfessor
{
    // Para o EF Core materializar do banco.
    private VinculoProfessor()
    {
    }

    public VinculoProfessor(CadastroElegivel professor, Turma turma)
    {
        ArgumentNullException.ThrowIfNull(professor);
        ArgumentNullException.ThrowIfNull(turma);

        if (!professor.EhProfessor)
        {
            throw new DomainException($"Só professor se vincula a turma; {professor.Email} é {professor.Papeis}.");
        }

        Id = Guid.CreateVersion7();
        ProfessorId = professor.Id;
        TurmaId = turma.Id;
    }

    public Guid Id { get; private set; }

    public Guid ProfessorId { get; private set; }

    public Guid TurmaId { get; private set; }
}
namespace Maxx.Domain.Academico;

// Vínculo aluno e turma. Única fonte de "quantas matérias o aluno tem no período".
public sealed class Matricula
{
    // Para o EF Core materializar do banco.
    private Matricula()
    {
    }

    public Matricula(CadastroElegivel aluno, Turma turma)
    {
        ArgumentNullException.ThrowIfNull(aluno);
        ArgumentNullException.ThrowIfNull(turma);

        if (!aluno.EhAluno)
        {
            throw new DomainException($"Só aluno se matricula em turma; {aluno.Email} é {aluno.Papeis}.");
        }

        if (turma.Materia.CursoId != aluno.CursoId)
        {
            throw new DomainException(
                $"{aluno.Email} não pode se matricular em {turma.Materia.Nome}: a matéria é de outro curso.");
        }

        Id = Guid.CreateVersion7();
        AlunoId = aluno.Id;
        TurmaId = turma.Id;
    }

    public Guid Id { get; private set; }

    // Aponta para o CadastroElegivel: a faculdade matricula antes de o aluno ter conta.
    public Guid AlunoId { get; private set; }

    public Guid TurmaId { get; private set; }
}
namespace Maxx.Domain.Academico;

public sealed class Curso
{
    // Para o EF Core materializar do banco.
    private Curso()
    {
        Nome = null!;
        Sigla = null!;
    }

    public Curso(string nome, string sigla, int duracaoEmSemestres)
    {
        sigla = Texto.Obrigatorio(sigla, "A sigla do curso");

        // A sigla vira o sufixo do arroba (@guilhermeGimenes-CC).
        if (!sigla.All(char.IsAsciiLetterUpper))
        {
            throw new DomainException($"A sigla do curso ({sigla}) só pode ter letras maiúsculas sem acento.");
        }

        if (duracaoEmSemestres < 1)
        {
            throw new DomainException($"O curso {sigla} precisa durar ao menos um semestre.");
        }

        Id = Guid.CreateVersion7();
        Nome = Texto.Obrigatorio(nome, "O nome do curso");
        Sigla = sigla;
        DuracaoEmSemestres = duracaoEmSemestres;
    }

    public Guid Id { get; private set; }

    public string Nome { get; private set; }

    public string Sigla { get; private set; }

    public int DuracaoEmSemestres { get; private set; }
}
namespace Maxx.Domain;

// Regra de produto violada. A borda traduz para o formato único de erro; a mensagem é
// para quem lê o log, não para o usuário final.
public sealed class DomainException : Exception
{
    public DomainException()
    {
    }

    public DomainException(string message) : base(message)
    {
    }

    public DomainException(string message, Exception innerException) : base(message, innerException)
    {
    }
}
using System.Reflection;
using System.Text.Json.Serialization;
using Maxx.Api.Health;
using Maxx.Infrastructure;
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;

// `Maxx.Api migrate` roda as migrations e sai. É o comando do contêiner de migração.
var isMigrate = args is ["migrate", ..];

// `Maxx.Api seed <base|demo>` grava os dados de data/ e sai. Idempotente.
var isSeed = args is ["seed", ..];

// A geração do OpenAPI no build sobe a aplicação sem servidor e sem banco.
var isOpenApiGeneration = Assembly.GetEntryAssembly()?.GetName().Name == "GetDocument.Insider";

var builder = WebApplication.CreateBuilder(
    isMigrate ? args[1..] : isSeed ? args[Math.Min(2, args.Length)..] : args);

var connectionString = builder.Configuration.GetConnectionString("Maxx")
    ?? (isOpenApiGeneration ? "Host=openapi-generation" : null)
    ?? throw new InvalidOperationException("ConnectionStrings:Maxx não configurada.");

builder.Services.AddProblemDetails();

// Número só como número: o padrão web aceita "42" em texto, e o contrato viraria
// `number | string` em todo campo numérico do cliente TypeScript.
builder.Services.ConfigureHttpJsonOptions(options =>
    options.SerializerOptions.NumberHandling = JsonNumberHandling.Strict);

builder.Services.AddOpenApi(options => options.AddDocumentTransformer((document, _, _) =>
{
    document.Info.Title = "Maxx API";
    document.Info.Version = "v1";
    return Task.CompletedTask;
}));
builder.Services.AddInfrastructure(connectionString);
builder.Services.Configure<SeedOptions>(builder.Configuration.GetSection(SeedOptions.Section));

var app = builder.Build();

if (isMigrate)
{
    await using var scope = app.Services.CreateAsyncScope();
    await scope.ServiceProvider.GetRequiredService<DatabaseMigrator>().MigrateAsync(CancellationToken.None);
    return 0;
}

if (isSeed)
{
    if (args is not [_, var nomeDoPerfil, ..] || !Enum.TryParse<PerfilDeSeed>(nomeDoPerfil, ignoreCase: true, out var perfil)
        || !Enum.IsDefined(perfil))
    {
        await Console.Error.WriteLineAsync("Uso: Maxx.Api seed <base|demo>");
        return 2;
    }

    await using var scope = app.Services.CreateAsyncScope();
    try
    {
        await scope.ServiceProvider.GetRequiredService<DatabaseSeeder>().SeedAsync(perfil, CancellationToken.None);
    }
    catch (SeedException ex)
    {
        // Dado recusado é resposta esperada, não falha do programa: sem pilha no log.
        await Console.Error.WriteLineAsync(ex.Message);
        return 1;
    }

    return 0;
}

// Um formato só de erro: ProblemDetails (RFC 9457).
app.UseExceptionHandler();
app.UseStatusCodePages();

// Origem única (ADR 0001): toda rota da API vive sob /api, e o Caddy não corta o prefixo.
var api = app.MapGroup("/api");
api.MapHealthEndpoints();

if (app.Environment.IsDevelopment())
{
    api.MapOpenApi("/openapi/{documentName}.json");
}

await app.RunAsync();
return 0;
{
  "Logging": {
    "LogLevel": {
      "Default": "Information",
      "Microsoft.AspNetCore": "Warning"
    }
  }
}
