}
using Maxx.Infrastructure.Persistence;
using Maxx.Infrastructure.Seed;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;
using Npgsql;

namespace Maxx.Infrastructure;

public static class DependencyInjection
{
    public static IServiceCollection AddInfrastructure(this IServiceCollection services, string connectionString)
    {
        services.AddNpgsqlDataSource(connectionString);

        services.AddDbContext<MaxxDbContext>((provider, options) =>
            MaxxDbContext.Configure(options, builder => builder.UseNpgsql(
                provider.GetRequiredService<NpgsqlDataSource>(),
                npgsql => npgsql.MigrationsHistoryTable(MaxxDbContext.MigrationsHistoryTable))));

        services.AddScoped<DatabaseMigrator>();
        services.AddScoped<DatabaseSeeder>();

        // Toda verificação registrada aqui entra no /ready.
        services.AddHealthChecks()
            .AddCheck<DatabaseReadinessCheck>("database", timeout: TimeSpan.FromSeconds(3));

        return services;
    }
}
namespace Maxx.Infrastructure.Seed;

public sealed class SeedOptions
{
    public const string Section = "Seed";

    // Onde estão catalogo/ e calendario/. Relativo ao diretório de trabalho: "data" na
    // raiz do repositório e em /app/data na imagem.
    public string DiretorioDeDados { get; set; } = "data";
}

public enum PerfilDeSeed
{
    // Estrutura: catálogo e calendário.
    Base,

    // O mundo fictício: cursos, matérias, turmas e pessoas. Exige o base.
    Demo,
}

public sealed record ResultadoDoSeedBase(
    int ItensNovos,
    int ItensAtualizados,
    int ItensInalterados,
    int FamiliasNovas,
    int FamiliasAtualizadas,
    int AnosNovos,
    int AnosAtualizados);

// Demo só acrescenta: o que já existe e bate com o arquivo fica como está.
public sealed record ResultadoDoSeedDemo(
    int CursosNovos,
    int MateriasNovas,
    int TurmasNovas,
    int CadastrosNovos,
    int MatriculasNovas,
    int VinculosNovos);
<Project Sdk="Microsoft.NET.Sdk.Web">

  <!--
    O documento OpenAPI só é gerado quando pedido (npm run gerar em packages/api-client),
    para nenhum build comum reescrever arquivo versionado.
  -->
  <PropertyGroup>
    <OpenApiGenerateDocuments>false</OpenApiGenerateDocuments>
    <OpenApiDocumentsDirectory>$(MSBuildThisFileDirectory)../../../../packages/api-client</OpenApiDocumentsDirectory>
    <OpenApiGenerateDocumentsOptions>--file-name openapi</OpenApiGenerateDocumentsOptions>
  </PropertyGroup>

  <ItemGroup>
    <ProjectReference Include="..\Maxx.Application\Maxx.Application.csproj" />
    <ProjectReference Include="..\Maxx.Infrastructure\Maxx.Infrastructure.csproj" />
  </ItemGroup>

  <ItemGroup>
    <PackageReference Include="Microsoft.AspNetCore.OpenApi" />
    <PackageReference Include="Microsoft.Extensions.ApiDescription.Server">
      <IncludeAssets>runtime; build; native; contentfiles; analyzers; buildtransitive</IncludeAssets>
      <PrivateAssets>all</PrivateAssets>
    </PackageReference>
  </ItemGroup>

</Project>
<Project Sdk="Microsoft.NET.Sdk">

  <ItemGroup>
    <ProjectReference Include="..\Maxx.Domain\Maxx.Domain.csproj" />
  </ItemGroup>

</Project>

