using System.Globalization;
using System.Text;

namespace Maxx.Domain.Identidade;

// A parte do arroba antes do hífen: a única que o usuário escolhe e a que é única no
// sistema, sem diferenciar maiúsculas (produto.md 2.3.1). Saber se um prefixo está livre
// é pergunta ao banco; aqui só a forma e a ordem das sugestões.
public static class PrefixoDeArroba
{
    public const int TamanhoMinimo = 3;

    public const int TamanhoMaximo = 30;

    // Teto de segurança: nenhum nome real chega perto disso.
    private const int TentativasNumeradas = 10_000;

    private static readonly HashSet<string> _particulas =
        new(["da", "de", "do", "das", "dos", "e"], StringComparer.OrdinalIgnoreCase);

    public static bool Mesmo(string prefixo, string outro) =>
        string.Equals(prefixo, outro, StringComparison.OrdinalIgnoreCase);

    // Letras ASCII e dígitos, de 3 a 30, começando por letra. Devolve como foi escrito.
    public static string Validar(string? prefixo)
    {
        if (prefixo is null
            || prefixo.Length < TamanhoMinimo
            || prefixo.Length > TamanhoMaximo
            || !char.IsAsciiLetter(prefixo[0])
            || !prefixo.All(char.IsAsciiLetterOrDigit))
        {
            throw new DomainException(
                $"O arroba tem de {TamanhoMinimo} a {TamanhoMaximo} letras sem acento e números, começando por letra.");
        }

        return prefixo;
    }

    // A primeira sugestão livre, na ordem de Sugestoes. estaLivre recebe o prefixo como
    // sugerido e responde sem diferenciar maiúsculas.
    public static string Sugerir(string nomeCompleto, Func<string, bool> estaLivre)
    {
        ArgumentNullException.ThrowIfNull(estaLivre);

        return Sugestoes(nomeCompleto).FirstOrDefault(estaLivre)
            ?? throw new DomainException($"Nenhuma sugestão de arroba livre para {nomeCompleto}.");
    }

    // Primeiro e último nome; depois com o primeiro nome do meio; depois primeiro e último
    // com número a partir de 2. Só candidatos válidos, sem repetição.
    public static IEnumerable<string> Sugestoes(string nomeCompleto)
    {
        var nomes = Nomes(nomeCompleto);
        var primeiroEUltimo = nomes.Count == 1 ? Juntar(nomes) : Juntar([nomes[0], nomes[^1]]);
        var comONomeDoMeio = nomes.Count >= 3 ? Juntar([nomes[0], nomes[1], nomes[^1]]) : null;

        return Candidatos(primeiroEUltimo, comONomeDoMeio)
            .Where(EhValido)
            .Distinct(StringComparer.OrdinalIgnoreCase);
    }

    private static IEnumerable<string> Candidatos(string primeiroEUltimo, string? comONomeDoMeio)
    {
        yield return Cortar(primeiroEUltimo, TamanhoMaximo);

        if (comONomeDoMeio is not null)
        {
            yield return Cortar(comONomeDoMeio, TamanhoMaximo);
        }

        for (var numero = 2; numero < TentativasNumeradas; numero++)
        {
            var sufixo = numero.ToString(CultureInfo.InvariantCulture);
            yield return Cortar(primeiroEUltimo, TamanhoMaximo - sufixo.Length) + sufixo;
        }
    }

    // Nome completo em palavras aproveitáveis: sem acento, sem cedilha, só letras e
    // dígitos ASCII, sem partícula.
    private static List<string> Nomes(string nomeCompleto)
    {
        var nomes = Texto.Obrigatorio(nomeCompleto, "O nome completo")
            .Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries)
            .Select(SoAscii)
            .Where(nome => nome.Length > 0 && !_particulas.Contains(nome))
            .ToList();

        if (nomes.Count == 0 || !char.IsAsciiLetter(nomes[0][0]))
        {
            throw new DomainException($"Não dá para sugerir arroba a partir de {nomeCompleto}.");
        }

        return nomes;
    }

    private static string SoAscii(string palavra)
    {
        var resultado = new StringBuilder(palavra.Length);
        foreach (var caractere in palavra.Normalize(NormalizationForm.FormD))
        {
            // A decomposição separa a letra do acento e da cedilha; o que sobra fora do
            // ASCII (acento solto, apóstrofo, hífen) é descartado.
            if (char.IsAsciiLetterOrDigit(caractere))
            {
                resultado.Append(caractere);
            }
        }

        return resultado.ToString();
    }

    private static string Juntar(IEnumerable<string> nomes) =>
        string.Concat(nomes.Select((nome, indice) => indice == 0
            ? nome.ToLowerInvariant()
            : char.ToUpperInvariant(nome[0]) + nome[1..].ToLowerInvariant()));

    private static string Cortar(string texto, int tamanho) => texto.Length <= tamanho ? texto : texto[..tamanho];

    private static bool EhValido(string prefixo) =>
        prefixo.Length is >= TamanhoMinimo and <= TamanhoMaximo
        && char.IsAsciiLetter(prefixo[0])
        && prefixo.All(char.IsAsciiLetterOrDigit);
}

using Maxx.Domain.Academico;

namespace Maxx.Domain.Identidade;

// A parte do arroba depois do hífen. Nunca escolhida pelo usuário: segue o papel e,
// para o aluno, o curso atual ou a marcação de ex-aluno (produto.md 2.3).
public static class Sufixo
{
    public const string ExAluno = "EX";

    public const string Professor = "PROF";

    public const string Instituicao = "UNIMAX";

    public static string Para(Papeis papeis, Curso? curso, bool exAluno)
    {
        if (papeis == Papeis.Aluno)
        {
            if (exAluno)
            {
                return ExAluno;
            }

            return curso?.Sigla ?? throw new DomainException("O sufixo do aluno exige o curso dele.");
        }

        // Professor e instituição na mesma conta usam o do professor.
        if (papeis.HasFlag(Papeis.Professor))
        {
            return Professor;
        }

        return papeis == Papeis.Instituicao
            ? Instituicao
            : throw new DomainException($"Sem sufixo de arroba para o papel {papeis}.");
    }
}

public sealed record Arroba(string Prefixo, string Sufixo)
{
    public override string ToString() => $"@{Prefixo}-{Sufixo}";
}

namespace Maxx.Domain.Identidade;

// De 8 a 128 caracteres, sem regra de composição (NIST SP 800-63B). Conta caractere, não
// unidade de UTF-16: um emoji é um. A mensagem nunca repete a senha.
public static class PoliticaDeSenha
{
    public const int TamanhoMinimo = 8;

    public const int TamanhoMaximo = 128;

    public static void Validar(string? senha)
    {
        var tamanho = senha?.EnumerateRunes().Count() ?? 0;
        if (tamanho is < TamanhoMinimo or > TamanhoMaximo)
        {
            throw new DomainException($"A senha tem de {TamanhoMinimo} a {TamanhoMaximo} caracteres.");
        }
    }
}

using Maxx.Domain.Academico;

namespace Maxx.Domain.Identidade;

// A conta. Liga-se a uma linha do cadastro elegível, uma para uma (um RA, uma conta), e é
// de lá que vem o papel. Aluno se cadastra pelo app; professor e instituição nascem do
// seed sem senha e definem a primeira pela recuperação (produto.md 2.5).
public sealed class Usuario
{
    private readonly List<PrefixoReservado> _prefixosReservados = [];

    // Para o EF Core materializar do banco.
    private Usuario()
    {
        NomeDeExibicao = null!;
        Prefixo = null!;
        Sufixo = null!;
    }

    private Usuario(
        CadastroElegivel cadastro, string nomeDeExibicao, string prefixo, string sufixo, string? hashDaSenha, DateTimeOffset agora)
    {
        Id = Guid.CreateVersion7();
        CadastroElegivelId = cadastro.Id;
        Papeis = cadastro.Papeis;
        NomeDeExibicao = Texto.Obrigatorio(nomeDeExibicao, "O nome de exibição");
        Prefixo = PrefixoDeArroba.Validar(prefixo);
        Sufixo = sufixo;
        HashDaSenha = hashDaSenha;
        CriadoEm = agora;
        _prefixosReservados.Add(new PrefixoReservado(Id, Prefixo, agora));
    }

    public Guid Id { get; private set; }

    public Guid CadastroElegivelId { get; private set; }

    public Papeis Papeis { get; private set; }

    public string NomeDeExibicao { get; private set; }

    // Como o usuário escreveu; a unicidade não diferencia maiúsculas.
    public string Prefixo { get; private set; }

    public string Sufixo { get; private set; }

    public Arroba Arroba => new(Prefixo, Sufixo);

    // Hash Argon2id no formato da infraestrutura. Nulo até o primeiro acesso de quem vem
    // do seed.
    public string? HashDaSenha { get; private set; }

    public bool TemSenha => HashDaSenha is not null;

    public DateTimeOffset? ExAlunoDesde { get; private set; }

    public bool EhExAluno => ExAlunoDesde is not null;

    public DateTimeOffset CriadoEm { get; private set; }

    // Todo prefixo que o usuário já teve, o atual inclusive. Nenhum volta a ser de outro.
    public IReadOnlyCollection<PrefixoReservado> PrefixosReservados => _prefixosReservados.AsReadOnly();

    public static Usuario CadastrarAluno(
        CadastroElegivel cadastro, Curso curso, string nomeDeExibicao, string prefixo, string hashDaSenha, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(cadastro);
        ArgumentNullException.ThrowIfNull(curso);

        if (!cadastro.EhAluno)
        {
            throw new DomainException($"Só aluno se cadastra pelo app; {cadastro.Email} é {cadastro.Papeis}.");
        }

        if (cadastro.CursoId != curso.Id)
        {
            throw new DomainException($"O curso {curso.Sigla} não é o do cadastro de {cadastro.Email}.");
        }

        return new Usuario(
            cadastro,
            nomeDeExibicao,
            prefixo,
            Identidade.Sufixo.Para(cadastro.Papeis, curso, exAluno: false),
            Texto.Obrigatorio(hashDaSenha, "O hash da senha"),
            agora);
    }

    public static Usuario CriarPeloSeed(CadastroElegivel cadastro, string prefixo, DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(cadastro);

        if (cadastro.EhAluno)
        {
            throw new DomainException($"Aluno se cadastra pelo app, não pelo seed: {cadastro.Email}.");
        }

        return new Usuario(
            cadastro,
            cadastro.NomeCompleto,
            prefixo,
            Identidade.Sufixo.Para(cadastro.Papeis, curso: null, exAluno: false),
            hashDaSenha: null,
            agora);
    }

    // Primeiro acesso e recuperação de senha. A política já passou sobre a senha em claro.
    public void DefinirSenha(string hashDaSenha) => HashDaSenha = Texto.Obrigatorio(hashDaSenha, "O hash da senha");

    public bool PossuiPrefixo(string prefixo) =>
        _prefixosReservados.Any(reservado => PrefixoDeArroba.Mesmo(reservado.Prefixo, prefixo));

    // Só a forma e a reserva do próprio dono. Se o prefixo está livre de terceiros é
    // pergunta ao banco, feita antes por quem chama e garantida pelo índice único.
    public void EditarPrefixo(string novo, DateTimeOffset agora)
    {
        novo = PrefixoDeArroba.Validar(novo);

        if (!PossuiPrefixo(novo))
        {
            _prefixosReservados.Add(new PrefixoReservado(Id, novo, agora));
        }

        Prefixo = novo;
    }

    // O prefixo é do dono; o sufixo novo nunca colide com ninguém.
    public void TrocarDeCurso(Curso curso)
    {
        ArgumentNullException.ThrowIfNull(curso);
        GarantirAlunoAtivo("trocar de curso");

        Sufixo = Identidade.Sufixo.Para(Papeis, curso, exAluno: false);
    }

    public void MarcarExAluno(DateTimeOffset agora)
    {
        GarantirAlunoAtivo("virar ex-aluno");

        ExAlunoDesde = agora;
        Sufixo = Identidade.Sufixo.ExAluno;
    }

    private void GarantirAlunoAtivo(string acao)
    {
        if (Papeis != Papeis.Aluno)
        {
            throw new DomainException($"Só aluno pode {acao}; @{Prefixo} é {Papeis}.");
        }

        if (EhExAluno)
        {
            throw new DomainException($"@{Prefixo} já é ex-aluno e não pode {acao}.");
        }
    }
}

// Um prefixo que já foi do usuário. A unicidade do prefixo no sistema mora aqui.
public sealed class PrefixoReservado
{
    // Para o EF Core materializar do banco.
    private PrefixoReservado()
    {
        Prefixo = null!;
    }

    internal PrefixoReservado(Guid usuarioId, string prefixo, DateTimeOffset reservadoEm)
    {
        UsuarioId = usuarioId;
        Prefixo = prefixo;
        ReservadoEm = reservadoEm;
    }

    public Guid UsuarioId { get; private set; }

    public string Prefixo { get; private set; }

    public DateTimeOffset ReservadoEm { get; private set; }
}

