using Maxx.Application.Autenticacao;

namespace Maxx.Api.Autenticacao;

// Como a sessão chega ao cliente (decisoes/README.md, Autenticação): na web o refresh vai
// em cookie HttpOnly e nunca no corpo; no nativo vai no corpo, para o secure store. O
// access token vai sempre no corpo, para ficar só em memória.
internal static class SessaoHttp
{
    public const string CabecalhoDoCliente = "X-Maxx-Cliente";

    public const string ClienteWeb = "web";

    public const string CookieDoRefresh = "maxx_refresh";

    // Só as rotas de autenticação recebem o cookie: nenhuma outra rota o vê.
    public const string CaminhoDoCookie = "/api/v1/auth";

    public static bool EhWeb(HttpRequest request) =>
        string.Equals(request.Headers[CabecalhoDoCliente], ClienteWeb, StringComparison.OrdinalIgnoreCase);

    public static SessaoResponse Escrever(HttpContext httpContext, Sessao sessao)
    {
        if (!EhWeb(httpContext.Request))
        {
            return SessaoResponse.De(sessao, refreshNoCorpo: true);
        }

        httpContext.Response.Cookies.Append(CookieDoRefresh, sessao.Refresh, new CookieOptions
        {
            HttpOnly = true,
            Secure = true,
            SameSite = SameSiteMode.Strict,
            Path = CaminhoDoCookie,
            Expires = sessao.RefreshExpiraEm,
            IsEssential = true,
        });

        return SessaoResponse.De(sessao, refreshNoCorpo: false);
    }
}

public sealed record SessaoResponse(
    string AccessToken, DateTimeOffset AccessTokenExpiraEm, string? RefreshToken, DateTimeOffset RefreshTokenExpiraEm)
{
    internal static SessaoResponse De(Sessao sessao, bool refreshNoCorpo) =>
        new(sessao.AccessToken.Valor, sessao.AccessToken.ExpiraEm, refreshNoCorpo ? sessao.Refresh : null, sessao.RefreshExpiraEm);
}

using Maxx.Domain;
using Microsoft.AspNetCore.Diagnostics;
using Microsoft.AspNetCore.Mvc;

namespace Maxx.Api.Erros;

// Regra de domínio que escapou da validação de borda vira 400 no formato único. A
// mensagem da exceção é para o log, não para o usuário (DomainException): a resposta leva
// só o código, que o cliente traduz em texto amigável.
internal sealed partial class DomainExceptionHandler(
    IProblemDetailsService problemDetails, ILogger<DomainExceptionHandler> logger) : IExceptionHandler
{
    public const string Codigo = "requisicao-invalida";

    public async ValueTask<bool> TryHandleAsync(HttpContext httpContext, Exception exception, CancellationToken cancellationToken)
    {
        if (exception is not DomainException domainException)
        {
            return false;
        }

        LogRecusada(logger, domainException.Message);

        httpContext.Response.StatusCode = StatusCodes.Status400BadRequest;
        return await problemDetails.TryWriteAsync(new ProblemDetailsContext
        {
            HttpContext = httpContext,
            Exception = exception,
            ProblemDetails = new ProblemDetails
            {
                Status = StatusCodes.Status400BadRequest,
                Title = "Requisição inválida.",
                Extensions = { [Erro.CampoCodigo] = Codigo },
            },
        });
    }

    [LoggerMessage(Level = LogLevel.Information, Message = "Requisição recusada pelo domínio: {Motivo}")]
    private static partial void LogRecusada(ILogger logger, string motivo);
}

// O formato único de erro: ProblemDetails (RFC 9457) com a extensão "codigo", estável e
// em kebab-case, que o cliente usa para escolher a mensagem amigável.
public static class Erro
{
    public const string CampoCodigo = "codigo";

    // Toda resposta de erro sai com código: quem não trouxe o seu ganha o do status.
    public static void Customizar(ProblemDetailsOptions options)
    {
        ArgumentNullException.ThrowIfNull(options);

        options.CustomizeProblemDetails = context =>
        {
            var problema = context.ProblemDetails;
            if (problema.Extensions.ContainsKey(CampoCodigo))
            {
                return;
            }

            problema.Extensions[CampoCodigo] = problema switch
            {
                HttpValidationProblemDetails => "dados-invalidos",
                _ => problema.Status switch
                {
                    StatusCodes.Status400BadRequest => "requisicao-invalida",
                    StatusCodes.Status401Unauthorized => "nao-autenticado",
                    StatusCodes.Status403Forbidden => "sem-permissao",
                    StatusCodes.Status404NotFound => "nao-encontrado",
                    StatusCodes.Status429TooManyRequests => "limite-de-taxa",
                    StatusCodes.Status503ServiceUnavailable => "indisponivel",
                    _ => "erro-interno",
                },
            };
        };
    }
}

