# Login, refresh rotativo e logout

Login próprio, sem cadastro público nem login social. O aluno entra por RA ou por
e-mail; professor e instituição, por e-mail. Implementado no passo 3.

```mermaid
sequenceDiagram
  participant App as App (web ou nativo)
  participant API
  participant DB as Postgres

  App->>API: login (RA ou e-mail + senha)
  Note over API: limite de taxa no login, por replica
  API->>DB: busca o usuario pelo RA ou pelo e-mail
  API->>API: verifica a senha com Argon2id
  alt credencial invalida
    API-->>App: recusado
  else credencial valida
    API->>DB: cria a familia F e o refresh R1
    API-->>App: access curto (sub e papeis) + refresh R1
    Note over App: web guarda o refresh em cookie HttpOnly<br/>nativo guarda no secure store<br/>access fica so em memoria
  end

  App->>API: refresh com R1
  API->>DB: marca R1 como rotacionado, emite R2 na familia F
  API-->>App: access novo + refresh R2

  App->>API: refresh com R1 de novo (roubo ou replay)
  API->>DB: R1 ja rotacionado, revoga a familia F inteira
  API-->>App: 401, sessao encerrada em todos os dispositivos

  App->>API: logout
  API->>DB: revoga a familia do refresh atual
  API-->>App: sessao encerrada
```

## De onde vem cada passo

| Passo | Fonte |
|---|---|
| RA ou e-mail para aluno; só e-mail para professor e instituição | `produto.md` 2.5 |
| Limite de taxa no login, por réplica, com o limitador nativo | `decisoes/README.md` (Limite de taxa); `plano-mestre.md` passo 3 |
| Argon2id; senha nunca em texto nem em log | ADR 0006; `CLAUDE.md` (Segurança) |
| Access curto com `sub` e papéis, sem a lista de turmas do professor | ADR 0006 |
| Refresh em cookie `HttpOnly` na web e no secure store no nativo | ADR 0006; cookie first-party pela origem única, ADR 0001 |
| Rotação por família; reuso de token já rotacionado derruba a família inteira | ADR 0006; `CLAUDE.md` (Segurança) |
| Logout revogando | `plano-mestre.md` passo 3 |

O papel do usuário vem do cadastro na base, nunca do domínio do e-mail (`produto.md`
2.4). Os códigos HTTP e o texto das respostas ficam para o passo 3; o único fixado aqui
é o 401 do reuso de refresh, que vem do ADR 0006. A resposta de credencial inválida que
não permita enumerar usuários é responsabilidade registrada no mesmo ADR.
using Maxx.Domain.Academico;
using Maxx.Domain.Identidade;

namespace Maxx.Application.Autenticacao;

public interface ICadastroElegivelRepository
{
    // A linha de aluno em que RA e e-mail estão juntos, com o curso dela. E-mail sem
    // diferenciar maiúsculas.
    Task<(CadastroElegivel Cadastro, Curso Curso)?> BuscarAlunoAsync(string ra, string email, CancellationToken cancellationToken);
}

public interface IUsuarioRepository
{
    Task<bool> ExisteParaCadastroAsync(Guid cadastroElegivelId, CancellationToken cancellationToken);

    // Dos candidatos, os que já são de alguém, comparados sem diferenciar maiúsculas.
    Task<IReadOnlySet<string>> PrefixosOcupadosAsync(IReadOnlyCollection<string> candidatos, CancellationToken cancellationToken);

    void Adicionar(Usuario usuario);
}

public interface IFamiliaDeSessaoRepository
{
    void Adicionar(FamiliaDeSessao familia);
}
using Maxx.Domain.Identidade;

namespace Maxx.Application.Autenticacao;

// Abre uma sessão: família nova com o primeiro refresh, mais o access token. Usado no
// cadastro, no login e na entrada da demonstração. Quem chama grava.
public sealed class SessaoService(
    ITokenGenerator tokens, IAccessTokenIssuer accessTokens, IFamiliaDeSessaoRepository familias, TimeProvider relogio)
{
    public Sessao Abrir(Usuario usuario)
    {
        ArgumentNullException.ThrowIfNull(usuario);

        var refresh = tokens.Generate();
        var familia = FamiliaDeSessao.Abrir(usuario.Id, refresh.Hash, relogio.GetUtcNow());
        familias.Adicionar(familia);

        return new Sessao(accessTokens.Issue(usuario), refresh.Valor, familia.Tokens.Single().ExpiraEm);
    }
}

// O que o cliente recebe ao entrar. O valor do refresh existe só aqui, em memória, no
// caminho até a resposta: o banco guarda o hash.
public sealed record Sessao(AccessToken AccessToken, string Refresh, DateTimeOffset RefreshExpiraEm);
namespace Maxx.Application.Autenticacao;

// Os códigos de recusa da autenticação, como o cliente os recebe em ProblemDetails.
public static class CodigosDeRecusa
{
    public const string CadastroNaoEncontrado = "cadastro-nao-encontrado";

    // O RA já tem conta: o cliente leva à recuperação de senha (produto.md 2.5).
    public const string ContaExistente = "conta-existente";

    public const string PrefixoInvalido = "prefixo-invalido";

    public const string PrefixoIndisponivel = "prefixo-indisponivel";

    public const string SenhaForaDaPolitica = "senha-fora-da-politica";

    public const string NomeDeExibicaoInvalido = "nome-de-exibicao-invalido";
}
using Maxx.Domain.Identidade;

namespace Maxx.Application.Autenticacao;

// O que a autenticação precisa e a Application não implementa: hash de senha, valor e
// hash de token opaco (refresh, recuperação), emissão do access token.

public interface ISenhaHasher
{
    // Argon2id, com sal novo a cada chamada. A senha em claro nunca sai daqui.
    string Hash(string senha);

    bool Verify(string senha, string hash);

    // O mesmo custo de um Verify, contra um hash fictício: login de quem não existe não
    // responde mais rápido que senha errada (ADR 0006, enumeração de usuário).
    void VerifyDummy(string senha);
}

public interface ITokenGenerator
{
    // Valor aleatório para o cliente e o hash dele para o banco.
    TokenOpaco Generate();

    // O hash de um valor que o cliente apresentou, para buscar no banco.
    string Hash(string valor);
}

public sealed record TokenOpaco(string Valor, string Hash);

public interface IAccessTokenIssuer
{
    AccessToken Issue(Usuario usuario);
}

public sealed record AccessToken(string Valor, DateTimeOffset ExpiraEm);
namespace Maxx.Application;

// Um pedido que a aplicação recusa por regra, não por falha: a borda traduz o tipo em
// status HTTP e devolve o código no formato único de erro. A mensagem é só para o log.
public sealed class RecusaException : Exception
{
    public RecusaException()
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message) : base(message)
    {
        Codigo = string.Empty;
    }

    public RecusaException(string message, Exception innerException) : base(message, innerException)
    {
        Codigo = string.Empty;
    }

    public RecusaException(TipoDeRecusa tipo, string codigo, string? motivoParaLog = null)
        : base(motivoParaLog ?? codigo)
    {
        Tipo = tipo;
        Codigo = codigo;
    }

    public TipoDeRecusa Tipo { get; }

    // Estável e em kebab-case: é o que o cliente usa para escolher a mensagem amigável.
    public string Codigo { get; }
}

public enum TipoDeRecusa
{
    Invalido,
    NaoEncontrado,
    Conflito,
    NaoAutorizado,
}

// Gravação recusada por uma unicidade do banco: a corrida que a checagem prévia não
// consegue fechar sozinha.
public sealed class ConflitoDeUnicidadeException : Exception
{
    public ConflitoDeUnicidadeException()
    {
    }

    public ConflitoDeUnicidadeException(string message) : base(message)
    {
    }

    public ConflitoDeUnicidadeException(string message, Exception innerException) : base(message, innerException)
    {
    }

    public ConflitoDeUnicidadeException(Unicidade unicidade, Exception innerException)
        : base($"Unicidade violada: {unicidade}.", innerException)
    {
        Unicidade = unicidade;
    }

    public Unicidade Unicidade { get; }
}

public enum Unicidade
{
    Outra,
    ContaPorCadastro,
    Prefixo,
}

public interface IUnitOfWork
{
    // Lança ConflitoDeUnicidadeException quando o banco recusa por unicidade.
    Task SalvarAsync(CancellationToken cancellationToken);
}

