namespace Maxx.Domain.Academico;

// Professor cadastrado por turma, a cada semestre. É a fonte do escopo de turma checado
// no banco a cada mutação de prêmio.
public sealed class VinculoProfessor
{
    // Para o EF Core materializar do banco.
    private VinculoProfessor()
    {
    }

    public VinculoProfessor(CadastroElegivel professor, Turma turma)
    {
        ArgumentNullException.ThrowIfNull(professor);
        ArgumentNullException.ThrowIfNull(turma);

        if (!professor.EhProfessor)
        {
            throw new DomainException($"Só professor se vincula a turma; {professor.Email} é {professor.Papeis}.");
        }

        Id = Guid.CreateVersion7();
        ProfessorId = professor.Id;
        TurmaId = turma.Id;
    }

    public Guid Id { get; private set; }

    public Guid ProfessorId { get; private set; }

    public Guid TurmaId { get; private set; }
}
namespace Maxx.Domain.Academico;

// Matéria mais semestre letivo. Professores vinculados e alunos matriculados por turma.
public sealed class Turma
{
    // Para o EF Core materializar do banco.
    private Turma() => Materia = null!;

    public Turma(Materia materia, SemestreLetivo semestre)
    {
        ArgumentNullException.ThrowIfNull(materia);
        ArgumentNullException.ThrowIfNull(semestre);

        Id = Guid.CreateVersion7();
        Materia = materia;
        MateriaId = materia.Id;
        SemestreLetivoId = semestre.Id;
    }

    public Guid Id { get; private set; }

    public Guid MateriaId { get; private set; }

    public Materia Materia { get; private set; }

    public Guid SemestreLetivoId { get; private set; }
}
namespace Maxx.Domain.Academico;

// O semestre letivo (2026/2) corta ranking e conquistas. Não confundir com o semestre do
// aluno, que é só perfil. Começa no primeiro dia do primeiro bimestre e termina no último
// dia do segundo: férias e recesso ficam fora.
public sealed class SemestreLetivo
{
    public const int PorAno = 2;
    public const int BimestresPorSemestre = 2;

    private readonly List<Bimestre> _bimestres;

    // Para o EF Core materializar do banco.
    private SemestreLetivo() => _bimestres = [];

    public SemestreLetivo(int ano, int numero, Bimestre primeiro, Bimestre segundo)
    {
        ArgumentNullException.ThrowIfNull(primeiro);
        ArgumentNullException.ThrowIfNull(segundo);

        if (ano < 1)
        {
            throw new DomainException($"Ano {ano} inválido.");
        }

        if (numero is < 1 or > PorAno)
        {
            throw new DomainException($"Semestre {numero} não existe: o ano letivo tem {PorAno}.");
        }

        var esperado = ((numero - 1) * BimestresPorSemestre) + 1;
        if (primeiro.Numero != esperado || segundo.Numero != esperado + 1)
        {
            throw new DomainException(
                $"O semestre {ano}/{numero} tem os bimestres {esperado} e {esperado + 1}, " +
                $"não {primeiro.Numero} e {segundo.Numero}.");
        }

        if (segundo.Inicio <= primeiro.Fim)
        {
            throw new DomainException(
                $"No semestre {ano}/{numero}, o bimestre {segundo.Numero} começa antes de o {primeiro.Numero} terminar.");
        }

        Id = Guid.CreateVersion7();
        Ano = ano;
        Numero = numero;
        _bimestres = [primeiro, segundo];
    }

    public Guid Id { get; private set; }

    public int Ano { get; private set; }

    public int Numero { get; private set; }

    public string Codigo => $"{Ano}/{Numero}";

    // Ordenado na leitura: vindo do banco, a coleção não garante ordem.
    public IReadOnlyList<Bimestre> Bimestres => [.. _bimestres.OrderBy(bimestre => bimestre.Numero)];

    public DateOnly Inicio => _bimestres.Min(bimestre => bimestre.Inicio);

    public DateOnly Fim => _bimestres.Max(bimestre => bimestre.Fim);

    public bool Contem(DateOnly data) => data >= Inicio && data <= Fim;
}
namespace Maxx.Domain.Academico;

// Instantes são guardados em UTC; as fronteiras de bimestre, semestre e ano são datas
// interpretadas em America/Sao_Paulo.
public static class FusoHorario
{
    public static TimeZoneInfo SaoPaulo { get; } = TimeZoneInfo.FindSystemTimeZoneById("America/Sao_Paulo");

    public static DateOnly DataLocal(DateTimeOffset instante) =>
        DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(instante, SaoPaulo).DateTime);
}
namespace Maxx.Domain.Academico;

// Aluno nunca acumula papel. O único acúmulo possível é professor e instituição na
// mesma conta.
[Flags]
public enum Papeis
{
    Nenhum = 0,
    Aluno = 1,
    Professor = 2,
    Instituicao = 4,
}
using System.Security.Claims;
using Microsoft.AspNetCore.Http.HttpResults;

namespace Maxx.Api.Autenticacao;

internal static class EuEndpoints
{
    // Quem é o dono do access token. Nasce mínimo na E5 para exercitar a autenticação;
    // cresce só por acréscimo.
    public static IEndpointRouteBuilder MapEuEndpoints(this IEndpointRouteBuilder routes)
    {
        routes.MapGet("/eu", GetEu)
            .WithName("GetEu")
            .WithTags("Autenticacao")
            .RequireAuthorization()
            .ProducesProblem(StatusCodes.Status401Unauthorized);

        return routes;
    }

    private static Ok<EuResponse> GetEu(ClaimsPrincipal usuario) =>
        TypedResults.Ok(new EuResponse(
            Guid.Parse(usuario.FindFirstValue(MaxxClaims.Sub)!),
            [.. usuario.FindAll(MaxxClaims.Papel).Select(claim => claim.Value)]));
}

public sealed record EuResponse(Guid Id, IReadOnlyList<string> Papeis);
using Maxx.Application.Autenticacao;
using Maxx.Domain.Academico;
using Maxx.Domain.Identidade;
using Microsoft.IdentityModel.JsonWebTokens;
using Microsoft.IdentityModel.Tokens;

namespace Maxx.Api.Autenticacao;

// Access token curto com sub e papéis, e nada mais: a lista de turmas do professor nunca
// entra no token (ADR 0006).
internal sealed class JwtAccessTokenIssuer(ChaveDeAssinatura chave, TimeProvider relogio) : IAccessTokenIssuer
{
    private readonly JsonWebTokenHandler _handler = new();

    public AccessToken Issue(Usuario usuario)
    {
        ArgumentNullException.ThrowIfNull(usuario);

        var agora = relogio.GetUtcNow();
        var expiraEm = agora + JwtOptions.Validade;

        var claims = new Dictionary<string, object>
        {
            [MaxxClaims.Sub] = usuario.Id.ToString(),
            [MaxxClaims.Papel] = NomesDosPapeis(usuario.Papeis),
        };

        var valor = _handler.CreateToken(new SecurityTokenDescriptor
        {
            Issuer = JwtOptions.Emissor,
            Audience = JwtOptions.Audiencia,
            Claims = claims,
            IssuedAt = agora.UtcDateTime,
            NotBefore = agora.UtcDateTime,
            Expires = expiraEm.UtcDateTime,
            SigningCredentials = new SigningCredentials(chave.Chave, SecurityAlgorithms.HmacSha256),
        });

        return new AccessToken(valor, expiraEm);
    }

    // Sempre lista, mesmo com um papel só: o cliente lê um formato só.
    internal static string[] NomesDosPapeis(Papeis papeis) =>
    [
        .. new[] { (Papeis.Aluno, "aluno"), (Papeis.Professor, "professor"), (Papeis.Instituicao, "instituicao") }
            .Where(papel => papeis.HasFlag(papel.Item1))
            .Select(papel => papel.Item2),
    ];
}

internal sealed record ChaveDeAssinatura(SymmetricSecurityKey Chave);
