31	    public async Task Token_emitido_pela_api_abre_o_eu_com_id_e_papeis()
32	    {
33	        await using var factory = ComChave(_chave);
34	        var renata = Professora(tambemInstituicao: true);
35	        var token = Emitir(factory, renata);
36	        using var client = factory.CreateClient();
37	
38	        var response = await client.SendAsync(Get(token.Valor), Ct);
39	
40	        Assert.Equal(HttpStatusCode.OK, response.StatusCode);
41	        var eu = await response.Content.ReadFromJsonAsync<EuResponse>(Ct);
