53	
54	        Assert.Equal(TimeSpan.FromMinutes(15), jwt.ValidTo - jwt.IssuedAt);
55	        Assert.Equal("HS256", jwt.Alg);
56	        Assert.Equal(
57	            new HashSet<string> { "sub", "papel", "iss", "aud", "iat", "nbf", "exp" },
58	            jwt.Claims.Select(claim => claim.Type).ToHashSet());
59	        Assert.Equal(["professor"], jwt.Claims.Where(claim => claim.Type == "papel").Select(claim => claim.Value));
