namespace Maxx.Application.Autenticacao.Login;

// O login (fluxos/01-login.md): aluno por RA ou por e-mail, professor e instituição só
// por e-mail. Toda falha tem a mesma resposta e o mesmo custo de um Argon2id, para que
// nem o corpo nem o tempo digam se a conta existe (ADR 0006).
public sealed class LoginHandler(IUsuarioRepository usuarios, ISenhaHasher senhas, SessaoService sessoes, IUnitOfWork unitOfWork)
{
    public async Task<Sessao> EntrarAsync(Credenciais credenciais, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(credenciais);

        // Com arroba é e-mail; sem, é RA. E-mail não tem forma de RA, nem RA de e-mail.
        var identificador = credenciais.Identificador.Trim();
        var usuario = identificador.Contains('@', StringComparison.Ordinal)
            ? await usuarios.BuscarPorEmailAsync(identificador, cancellationToken)
            : await usuarios.BuscarAlunoPorRaAsync(identificador, cancellationToken);

        // Conta do seed que ainda não definiu senha entra pela recuperação, não por aqui.
        if (usuario?.HashDaSenha is not { } hash)
        {
            senhas.VerifyDummy(credenciais.Senha);
            throw CredenciaisInvalidas("conta inexistente ou sem senha");
        }

        if (!senhas.Verify(credenciais.Senha, hash))
        {
            throw CredenciaisInvalidas($"senha errada para o usuário {usuario.Id}");
        }

        var sessao = sessoes.Abrir(usuario);
        await unitOfWork.SalvarAsync(cancellationToken);
        return sessao;
    }

    // O motivo vai só para o log; o identificador digitado não vai nem para lá.
    private static RecusaException CredenciaisInvalidas(string motivo) =>
        new(TipoDeRecusa.NaoAutorizado, CodigosDeRecusa.CredenciaisInvalidas, $"Login recusado: {motivo}.");
}

// A senha em claro existe só neste pedido, a caminho do Verify.
public sealed record Credenciais(string Identificador, string Senha)
{
    // Nunca imprimir a senha, nem por acidente num log de objeto.
    public override string ToString() => "Credenciais { }";
}

using Maxx.Domain.Identidade;

namespace Maxx.Application.Autenticacao.Login;

// A renovação: o refresh apresentado é trocado por um novo da mesma família, com um access
// novo. Reuso de um já trocado derruba a família (ADR 0006).
public sealed class RefreshHandler(
    IFamiliaDeSessaoRepository familias,
    IUsuarioRepository usuarios,
    ITokenGenerator tokens,
    IAccessTokenIssuer accessTokens,
    IUnitOfWork unitOfWork,
    TimeProvider relogio)
{
    public async Task<Renovacao> RenovarAsync(string refresh, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(refresh);

        try
        {
            return await TentarAsync(refresh, cancellationToken);
        }
        catch (ConflitoDeConcorrenciaException)
        {
            // Outro pedido rotacionou este mesmo refresh entre a leitura e a gravação. Relido,
            // ele já aparece rotacionado, e o reuso é tratado como se tivesse chegado depois:
            // simultâneo ou em sequência, o resultado é o mesmo (decisoes/README.md).
            unitOfWork.Descartar();
            return await TentarAsync(refresh, cancellationToken);
        }
    }

    private async Task<Renovacao> TentarAsync(string refresh, CancellationToken cancellationToken)
    {
        var hash = tokens.Hash(refresh);
        var familia = await familias.BuscarPorRefreshAsync(hash, cancellationToken);
        if (familia is null)
        {
            return Renovacao.Recusada(RecusaDaRenovacao.Desconhecido);
        }

        var novo = tokens.Generate();
        switch (familia.Rotacionar(hash, novo.Hash, relogio.GetUtcNow()))
        {
            case ResultadoDoRefresh.Rotacionado:
                var usuario = await usuarios.BuscarAsync(familia.UsuarioId, cancellationToken)
                    ?? throw new InvalidOperationException($"A família {familia.Id} cita um usuário que não existe.");
                await unitOfWork.SalvarAsync(cancellationToken);

                var emitido = familia.Tokens.Single(token => token.Hash == novo.Hash);
                return Renovacao.Concedida(new Sessao(accessTokens.Issue(usuario), novo.Valor, emitido.ExpiraEm), familia.Id);

            case ResultadoDoRefresh.ReusoDetectado:
                await unitOfWork.SalvarAsync(cancellationToken);
                return Renovacao.Recusada(RecusaDaRenovacao.ReusoDetectado, familia.Id);

            case ResultadoDoRefresh.Expirado:
                return Renovacao.Recusada(RecusaDaRenovacao.Expirado, familia.Id);

            default:
                return Renovacao.Recusada(RecusaDaRenovacao.FamiliaRevogada, familia.Id);
        }
    }
}

// Sem exceção para a recusa: na web a borda ainda precisa apagar o cookie na resposta.
public sealed record Renovacao(Sessao? Sessao, RecusaDaRenovacao? Recusa, Guid? FamiliaId)
{
    public static Renovacao Concedida(Sessao sessao, Guid familiaId) => new(sessao, null, familiaId);

    public static Renovacao Recusada(RecusaDaRenovacao recusa, Guid? familiaId = null) => new(null, recusa, familiaId);
}

public enum RecusaDaRenovacao
{
    Desconhecido,
    Expirado,
    FamiliaRevogada,

    // Este pedido acabou de revogar a família.
    ReusoDetectado,
}

using Maxx.Domain.Identidade;

namespace Maxx.Application.Autenticacao.Login;

// O logout revoga a família do refresh apresentado: o refresh atual e os que já foram
// trocados deixam de valer. Idempotente, e calado sobre refresh desconhecido.
public sealed class LogoutHandler(
    IFamiliaDeSessaoRepository familias, ITokenGenerator tokens, IUnitOfWork unitOfWork, TimeProvider relogio)
{
    public async Task SairAsync(string refresh, CancellationToken cancellationToken)
    {
        ArgumentNullException.ThrowIfNull(refresh);

        var familia = await familias.BuscarPorRefreshAsync(tokens.Hash(refresh), cancellationToken);
        if (familia is null)
        {
            return;
        }

        familia.Revogar(MotivoDaRevogacao.Logout, relogio.GetUtcNow());
        await unitOfWork.SalvarAsync(cancellationToken);
    }
}

