namespace Maxx.Domain.Identidade;

// Um pedido de recuperação de senha, que também é o primeiro acesso de quem vem do seed
// (docs/fluxos/06-recuperacao-de-senha.md). Token de uso único, por 30 minutos; o domínio
// só vê o hash dele.
public sealed class RecuperacaoDeSenha
{
    public static readonly TimeSpan Validade = TimeSpan.FromMinutes(30);

    // Para o EF Core materializar do banco.
    private RecuperacaoDeSenha()
    {
        Hash = null!;
    }

    private RecuperacaoDeSenha(Guid usuarioId, string hash, DateTimeOffset agora)
    {
        Id = Guid.CreateVersion7();
        UsuarioId = usuarioId;
        Hash = Texto.Obrigatorio(hash, "O hash do token de recuperação");
        SolicitadaEm = agora;
        ExpiraEm = agora + Validade;
    }

    public Guid Id { get; private set; }

    public Guid UsuarioId { get; private set; }

    public string Hash { get; private set; }

    public DateTimeOffset SolicitadaEm { get; private set; }

    public DateTimeOffset ExpiraEm { get; private set; }

    public DateTimeOffset? UsadaEm { get; private set; }

    // Outro pedido do mesmo usuário foi concluído antes deste.
    public DateTimeOffset? InvalidadaEm { get; private set; }

    public static RecuperacaoDeSenha Solicitar(Guid usuarioId, string hash, DateTimeOffset agora) => new(usuarioId, hash, agora);

    // Senha nova, todas as sessões do usuário derrubadas e os outros pedidos pendentes dele
    // invalidados, ou nada muda: um link antigo não redefine a senha de novo. A política já
    // passou sobre a senha em claro; aqui chega o hash. familiasDoUsuario e
    // outrosPedidosDoUsuario são os que quem chama carregou.
    public ResultadoDaRecuperacao Concluir(
        Usuario usuario,
        string hashDaSenhaNova,
        IEnumerable<FamiliaDeSessao> familiasDoUsuario,
        IEnumerable<RecuperacaoDeSenha> outrosPedidosDoUsuario,
        DateTimeOffset agora)
    {
        ArgumentNullException.ThrowIfNull(usuario);
        ArgumentNullException.ThrowIfNull(familiasDoUsuario);
        ArgumentNullException.ThrowIfNull(outrosPedidosDoUsuario);

        if (usuario.Id != UsuarioId)
        {
            throw new ArgumentException("A recuperação é de outro usuário.", nameof(usuario));
        }

        var familias = familiasDoUsuario.ToList();
        if (familias.Any(familia => familia.UsuarioId != UsuarioId))
        {
            throw new ArgumentException("Há família de sessão de outro usuário.", nameof(familiasDoUsuario));
        }

        var outrosPedidos = outrosPedidosDoUsuario.Where(pedido => pedido.Id != Id).ToList();
        if (outrosPedidos.Any(pedido => pedido.UsuarioId != UsuarioId))
        {
            throw new ArgumentException("Há pedido de recuperação de outro usuário.", nameof(outrosPedidosDoUsuario));
        }

        if (UsadaEm is not null)
        {
            return ResultadoDaRecuperacao.JaUsada;
        }

        if (InvalidadaEm is not null)
        {
            return ResultadoDaRecuperacao.Invalidada;
        }

        if (agora > ExpiraEm)
        {
            return ResultadoDaRecuperacao.Expirada;
        }

        usuario.DefinirSenha(hashDaSenhaNova);
        UsadaEm = agora;
        foreach (var familia in familias)
        {
            familia.Revogar(MotivoDaRevogacao.SenhaRedefinida, agora);
        }

        foreach (var pedido in outrosPedidos)
        {
            pedido.Invalidar(agora);
        }

        return ResultadoDaRecuperacao.Concluida;
    }

    // Só pedido ainda aberto: usado ou já invalidado fica como está.
    private void Invalidar(DateTimeOffset agora)
    {
        if (UsadaEm is null && InvalidadaEm is null)
        {
            InvalidadaEm = agora;
        }
    }
}

public enum ResultadoDaRecuperacao
{
    Concluida,
    Expirada,
    JaUsada,

    // Outro pedido do mesmo usuário foi concluído antes deste.
    Invalidada,
}
# Recuperação de senha e primeiro acesso

O mesmo fluxo serve a dois casos: o aluno que esqueceu a senha e o primeiro acesso de
professor e instituição, cuja conta nasce do seed sem senha. Implementado no passo 3; a
tela chega no passo 5.

```mermaid
sequenceDiagram
  participant App as App (web ou nativo)
  participant API
  participant DB as Postgres
  participant Envio as Envio em segundo plano
  participant SMTP

  App->>API: pede recuperacao (e-mail)
  Note over API: limite de taxa por e-mail, por replica
  API->>DB: busca o usuario pelo e-mail
  alt usuario existe
    API->>DB: grava o hash do token T, validade de 30 minutos
    API->>Envio: enfileira o e-mail com o link de T
  end
  API-->>App: 202, a mesma resposta exista o e-mail ou nao

  Envio->>SMTP: envia o link com T
  Note over Envio: fora da requisicao; fila em memoria ate o passo 6

  App->>API: confirma (T + senha nova)
  API->>DB: busca o token pelo hash de T
  alt T inexistente, expirado, ja usado ou invalidado
    API-->>App: recusado
  else T valido
    API->>API: hash da senha nova com Argon2id
    API->>DB: grava a senha, marca T como usado, revoga todas as familias de refresh
    API->>DB: invalida os outros pedidos pendentes do usuario
    API-->>App: senha redefinida, entrar de novo
  end
```

## De onde vem cada passo

| Passo | Fonte |
|---|---|
| Recuperação por e-mail desde a fase 1 | `produto.md` 2.5 |
| Primeiro acesso de professor e instituição por este fluxo | `produto.md` 2.5; `decisoes/README.md` (Autenticação) |
| Mesma resposta exista o e-mail ou não | ADR 0006 (enumeração de usuário); `decisoes/README.md` (Autenticação) |
| Token de 30 minutos, uso único, guardado só como hash | `decisoes/README.md` (Autenticação) |
| Limite de taxa por e-mail | `decisoes/README.md` (Autenticação) |
| Envio fora da requisição, em segundo plano até a fila do passo 6 | `decisoes/README.md` (Autenticação) |
| Senha nova revoga todas as famílias de refresh | `decisoes/README.md` (Autenticação) |
| Concluir um pedido invalida os outros pendentes do mesmo usuário: um link antigo não redefine a senha de novo | `decisoes/README.md` (Autenticação) |
